using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== ERRORS ===");
foreach (var e in errors)
{
    var project = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        if (node is Target t) { 
            node = t.Parent;
            if (node is Project pp) { project = pp.Name; break; }
        }
        node = node.Parent;
    }
    Console.WriteLine($"[PROJECT: {project}]");
    Console.WriteLine($"  File: {e.File}");
    Console.WriteLine($"  Line: {e.LineNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Message: {e.Text}");
    Console.WriteLine($"  Timestamp: {e.Timestamp}");
    Console.WriteLine();
}

Console.WriteLine("=== WARNINGS (last 20) ===");
foreach (var w in warnings.TakeLast(20))
{
    Console.WriteLine($"  [{w.Code}] {w.Text}");
}
