using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

// Get all projects and their build status
Console.WriteLine("=== PROJECT BUILD ORDER & STATUS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} -> Succeeded={p.Succeeded}");
}

// Check for dependency info
Console.WriteLine("\n=== PROJECT REFERENCES (from items) ===");
foreach (var p in projects)
{
    var addItems = p.FindChildrenRecursive<AddItem>().Where(a => a.Name == "ProjectReference");
    foreach (var item in addItems)
    {
        foreach (var child in item.Children)
        {
            Console.WriteLine($"  {p.Name} references: {child}");
        }
    }
}

// Check package references
Console.WriteLine("\n=== PACKAGE RESTORE ISSUES ===");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages.Where(m => m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("NU1") || m.Text.Contains("package"))))
{
    Console.WriteLine($"  {m.Text}");
}
